# mark zeros in any 2x2 all-zero block
out=[row[:] for row in g]
for r in range(26):
 for c in range(19):
  if all(g[rr][cc]==0 for rr in (r,r+1) for cc in (c,c+1)):
   for rr in (r,r+1):
    for cc in (c,c+1):out[rr][cc]=6
print('\n'.join(' '.join(map(str,row)) for row in out))

from collections import deque
out=[row[:] for row in g]; seen=set()
for r in range(27):
 for c in range(20):
  if g[r][c]==0 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); comp=[]
   while q:
    a,b=q.popleft();comp.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     p=(a+da,b+db)
     if 0<=p[0]<27 and 0<=p[1]<20 and g[p[0]][p[1]]==0 and p not in seen:seen.add(p);q.append(p)
   if any((a+1,b) in comp and (a,b+1) in comp and (a+1,b+1) in comp for a,b in comp):
    for a,b in comp:out[a][b]=6
print('\n'.join(' '.join(map(str,row)) for row in out))
